export function initialize(element, dotNetRef, timeoutMs) {
    let timer = null;
    let isIdle = false;

    const events = ["mousemove", "keydown", "click", "scroll"];

    function resetTimer() {
        clearTimeout(timer);

        if (isIdle) {
            isIdle = false;
            dotNetRef.invokeMethodAsync("OnUserActive");
        }

        timer = setTimeout(() => {
            isIdle = true;
            dotNetRef.invokeMethodAsync("OnUserIdle");
        }, timeoutMs);
    }

    for (const evt of events) {
        element.addEventListener(evt, resetTimer, { passive: true });
    }

    // Start the initial timer
    resetTimer();

    return {
        dispose() {
            clearTimeout(timer);
            for (const evt of events) {
                element.removeEventListener(evt, resetTimer);
            }
        },
        updateTimeout(newTimeoutMs) {
            timeoutMs = newTimeoutMs;
            resetTimer();
        }
    };
}

